import json
import unicodedata

VOWELS = set("aeiouɛɔ")


def strip_marks(s):
    return "".join(c for c in unicodedata.normalize("NFD", s)
                   if unicodedata.category(c) != "Mn")


def first_cvc(w):
    w = strip_marks(w)
    i = next(k for k, c in enumerate(w) if c in VOWELS)
    j = i + 1
    if j < len(w) and w[j] not in VOWELS:
        return w[:j + 1]
    return w[:j]


def rule_prefix_first_cvc(w):
    return first_cvc(w) + strip_marks(w)


north_pairs = [
    ("dakɛru", "darkɛru"), ("rɔbik", "rɔbrɔbik"), ("alema", "amlema"),
    ("makay", "makmakay"), ("apúk", "akpuk"), ("lɔpay", "lɔplɔpay"),
    ("payláwana", "paylawlawana"), ("kalpaŋir", "kalpaŋpaŋir"),
    ("garkɔ́w", "garkɔwkɔw"), ("ɛylɛka", "ɛylɛklɛka"),
    ("dubɛmna", "dumbɛmna"), ("maylɛwa", "maylɛwlɛwa"),
    ("matay", "matmatay"), ("mɔna", "mɔnmɔna"), ("bɛbar", "bɛbɛbar"),
    ("jaŋil", "jaŋjaŋil"), ("letna", "letletna"), ("ɛrnɔnaw", "ɛrnɔnɔnaw"),
]

candidates = {"prefix_first_cvc": rule_prefix_first_cvc}

evidence = {}
consistent = []
for name, rule in candidates.items():
    hits = [(r, n) for r, n in north_pairs if rule(r) == n]
    evidence[name] = {"matches": len(hits), "of": len(north_pairs)}
    if len(hits) == len(north_pairs):
        consistent.append(name)

if len(consistent) == 1:
    answer = candidates[consistent[0]]("dabuka")
else:
    answer = "UNSUPPORTED"

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "target": "(13) north dialect of dabuka",
        "candidate_rule_fit": evidence,
        "consistent_rules": consistent,
    },
}, ensure_ascii=False))
